    78→function parseAgent(filePath) {
    79→  try {
    80→    const content = fs.readFileSync(filePath, 'utf-8');
    81→    const { data, content: body } = matter(content);
    82→    const stats = fs.statSync(filePath);
    83→    return {
    84→      filename: path.basename(filePath, '.md'),
    85→      path: filePath,
    86→      frontmatter: data,
    87→      name: data.name || path.basename(filePath, '.md'),
    88→      description: data.description || '',
    89→      model: data.model || '',
    90→      tools: data.tools || '',
    91→      body: body.trim(),
    92→      raw: content,
    93→      updatedAt: stats.mtime.toISOString(),
    94→    };
    95→  } catch (e) {
    96→    return null;
    97→  }
    98→}
