   100→function listAgents(dir) {
   101→  try {
   102→    if (!fs.existsSync(dir)) return [];
   103→    return fs.readdirSync(dir)
   104→      .filter(f => f.endsWith('.md'))
   105→      .map(f => parseAgent(path.join(dir, f)))
   106→      .filter(Boolean);
   107→  } catch {
   108→    return [];
   109→  }
   110→}
