   112→function listMdFiles(dir) {
   113→  try {
   114→    if (!fs.existsSync(dir)) return [];
   115→    return fs.readdirSync(dir)
   116→      .filter(f => f.endsWith('.md'))
   117→      .map(f => {
   118→        const filePath = path.join(dir, f);
   119→        const content = readFileSafe(filePath);
   120→        const stats = fs.statSync(filePath);
   121→        return {
   122→          name: f.replace('.md', ''),
   123→          content: content || '',
   124→          path: filePath,
   125→          updatedAt: stats.mtime.toISOString(),
   126→        };
   127→      });
   128→  } catch {
   129→    return [];
   130→  }
   131→}
