   133→function discoverProjects(dirs) {
   134→  const projects = [];
   135→  for (const dir of dirs) {
   136→    const resolved = dir.replace(/^~/, HOME);
   137→    if (!fs.existsSync(resolved)) continue;
   138→    try {
   139→      const entries = fs.readdirSync(resolved, { withFileTypes: true });
   140→      for (const entry of entries) {
   141→        if (!entry.isDirectory()) continue;
   142→        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
   143→        const projectPath = path.join(resolved, entry.name);
   144→        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
   145→        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
   146→        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
   147→        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
   148→        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
   149→          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
   150→          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
   151→          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
   152→          projects.push({
   153→            id: Buffer.from(projectPath).toString('base64url'),
   154→            name: entry.name,
   155→            path: projectPath,
   156→            displayPath: projectPath.replace(HOME, '~'),
   157→            hasClaudeDir,
   158→            hasClaudeMd,
   159→            agentCount: agents.length,
   160→            commandCount: commands.length,
   161→            ruleCount: rules.length,
   162→            agents,
   163→            commands: commands.map(c => c.name),
   164→            rules: rules.map(r => r.name),
   165→          });
   166→        }
   167→      }
   168→    } catch {}
   169→  }
   170→  return projects;
   171→}
