   334→// --- Directory Browser ---
   335→app.get('/api/browse', (req, res) => {
   336→  let targetPath = (req.query.path || HOME).replace(/^~/, HOME);
   337→  targetPath = path.resolve(targetPath);
   338→
   339→  try {
   340→    if (!fs.existsSync(targetPath)) {
   341→      return res.status(404).json({ error: 'Path not found' });
   342→    }
   343→    const stat = fs.statSync(targetPath);
   344→    if (!stat.isDirectory()) {
   345→      return res.status(400).json({ error: 'Not a directory' });
   346→    }
   347→
   348→    const entries = fs.readdirSync(targetPath, { withFileTypes: true });
   349→    const dirs = entries
   350→      .filter(e => e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules' && e.name !== '__pycache__')
   351→      .map(e => ({
   352→        name: e.name,
   353→        path: path.join(targetPath, e.name),
   354→        displayPath: path.join(targetPath, e.name).replace(HOME, '~'),
   355→        hasProjects: false,
   356→      }))
   357→      .sort((a, b) => a.name.localeCompare(b.name));
   358→
   359→    for (const dir of dirs) {
   360→      try {
   361→        const sub = fs.readdirSync(dir.path, { withFileTypes: true });
   362→        dir.hasProjects = sub.some(s =>
   363→          s.isDirectory() && (
   364→            fs.existsSync(path.join(dir.path, s.name, '.claude')) ||
   365→            fs.existsSync(path.join(dir.path, s.name, 'CLAUDE.md')) ||
   366→            fs.existsSync(path.join(dir.path, s.name, 'package.json')) ||
   367→            fs.existsSync(path.join(dir.path, s.name, 'pubspec.yaml'))
   368→          )
   369→        );
   370→      } catch {}
   371→    }
   372→
   373→    const parts = targetPath.split(path.sep).filter(Boolean);
   374→    const breadcrumbs = parts.map((part, i) => ({
   375→      name: i === 0 && targetPath.startsWith(HOME) ? '~' : part,
   376→      path: path.sep + parts.slice(0, i + 1).join(path.sep),
   377→    }));
   378→
   379→    if (targetPath.startsWith(HOME)) {
   380→      const homeIndex = HOME.split(path.sep).filter(Boolean).length - 1;
   381→      breadcrumbs.splice(0, homeIndex + 1, { name: '~', path: HOME });
   382→    }
   383→
   384→    res.json({
   385→      current: targetPath,
   386→      displayPath: targetPath.replace(HOME, '~'),
   387→      parent: path.dirname(targetPath) !== targetPath ? path.dirname(targetPath) : null,
   388→      breadcrumbs,
   389→      directories: dirs,
   390→    });
   391→  } catch (e) {
   392→    res.status(500).json({ error: 'Cannot read directory' });
   393→  }
   394→});
