   618→// Claude AI chat — uses local `claude` CLI via stdin (no API key required)
   619→const { spawn } = require('child_process');
   620→
   621→app.post('/api/ai/chat', (req, res) => {
   622→  const { messages, system } = req.body;
   623→  if (!Array.isArray(messages) || messages.length === 0) {
   624→    return res.status(400).json({ error: 'messages array required' });
   625→  }
   626→
   627→  const systemText = system || 'You are an expert Claude Code assistant helping users write and improve their Claude agents, commands, rules, and CLAUDE.md files. Be concise and practical.';
   628→
   629→  let prompt = systemText + '\n\n';
   630→  for (const msg of messages) {
   631→    if (msg.role === 'user') prompt += `Human: ${msg.content}\n\n`;
   632→    else if (msg.role === 'assistant') prompt += `Assistant: ${msg.content}\n\n`;
   633→  }
   634→  prompt += 'Assistant:';
   635→
   636→  const claudePath = process.env.CLAUDE_PATH || 'claude';
   637→  const childEnv = { ...process.env, HOME: os.homedir() };
   638→  delete childEnv.CLAUDECODE;
   639→
   640→  // Use stdin to avoid OS argument length limits; -p without an argument reads from stdin
   641→  const proc = spawn(claudePath, ['-p'], {
   642→    env: childEnv,
   643→  });
   644→
   645→  let output = '';
   646→  let errOutput = '';
   647→  let done = false;
   648→
   649→  const timeout = setTimeout(() => {
   650→    if (!done) {
   651→      done = true;
   652→      proc.kill();
   653→      res.status(500).json({ error: 'Request timed out (60s). Try a shorter message.' });
   654→    }
   655→  }, 120000);
   656→
   657→  proc.stdout.on('data', (data) => { output += data.toString(); });
   658→  proc.stderr.on('data', (data) => { errOutput += data.toString(); });
   659→
   660→  proc.on('close', (code) => {
   661→    clearTimeout(timeout);
   662→    if (done) return;
   663→    done = true;
   664→    if (code !== 0) {
   665→      return res.status(500).json({ error: errOutput.trim() || `claude exited with code ${code}` });
   666→    }
   667→    res.json({ content: output.trim() });
   668→  });
   669→
   670→  proc.on('error', (err) => {
   671→    clearTimeout(timeout);
   672→    if (!done) {
   673→      done = true;
   674→      res.status(500).json({ error: `Failed to run claude: ${err.message}` });
   675→    }
   676→  });
   677→
   678→  // Write prompt via stdin and close
   679→  proc.stdin.write(prompt, 'utf8');
   680→  proc.stdin.end();
   681→});
